import React, { useEffect, useMemo, useState } from "react";
import { useNavigate, useSearchParams, Link } from 'react-router-dom';
import { Users2, Truck, Route, Wrench, ClipboardList, Timer, Clock, Calendar, Activity, Waves, Package, History, BarChart3, Plus, Trash2, RefreshCw, MapPin, ChevronRight, Link2, Share2, MoreVertical, KeyRound, Eye, EyeOff, Copy as CopyIcon, Undo2, ShieldAlert, Loader2, DollarSign, Pencil, FolderCog, AlertOctagon } from "lucide-react";
import { api } from "@/api";
import { SUPPLIER_METADATA } from "@/pages/settings/supplier_metadata";
import { mustConfirm } from "@/components/ui/confirm-dialog";
import { colors, money, gradients } from "@/theme";
import { useAuth } from "@/auth";
import { CustomerLink, AddressLink } from "@/components/customer";
import { usePermissions } from "@/hooks/usePermissions";
import { useIndustries } from "@/hooks/useIndustries";
import { PageHeader, Button, Skeleton, StatusPill, Chip, EmptyState, TextInput, Modal, Toast } from "@/components/ui-kit";
import { useAttendance } from "@/hooks/useAttendance";
import WorkstreamJobDrawer from "@/pages/ops/WorkstreamJobDrawer";
import EditItemModal from "@/components/pricebook/EditItemModal";
// Task C · Feb-2026 — Pricebook rows now embed a click-to-edit
// category combobox parameterized against ``PATCH /api/items/{id}``.
// Same component the Recurring Jobs table uses (parameterized in
// Task C · Commit 1 to accept a ``patchUrl`` prop).
import CategoryComboCell from "@/components/recurring/CategoryComboCell";
// Task E · Feb-2026 — Shared navy filter/search strip primitive
// consumed by six list pages (Customers, Invoices, Pricebook,
// Recurring Jobs, Work Stream, Payments Ledger).
import NavyFilterBar from "@/components/ui/NavyFilterBar";
// Feb-2026 · Live-Tech-Map · Phase 2 — Team colors ship. Replaces
// the free-form ``<input type="color">`` + hex-input pickers with
// the 12-chip palette picker so the UI can only produce colors
// that Phase 1 palette-locked backend endpoints accept.
import PaletteChipPicker from "@/components/team/PaletteChipPicker";
// Feb-2026 · Global Custom Color Picker · full picker (presets +
// recents + freeform + contrast guard).
import ColorPicker from "@/components/ui/ColorPicker";
// Feb-2026 · Sprint 2 · Section A — Admin "Unlinked Technicians"
// widget. Renders inside the Team tab above the roster list;
// self-hides for non-admins and when zero techs are unlinked.
import UnlinkedTechniciansWidget from "@/components/team/UnlinkedTechniciansWidget";

/* ═══ Ops hub – one page, many tabs. Kept compact by construction. ═══ */


// Feb-2026 · Live-Tech-Map Phase 2 — the ``CREW_COLOR_PRESETS``
// palette that used to live here (12 hand-picked hues) was
// retired when the Crews color picker migrated to the shared
// ``PaletteChipPicker`` (fed by ``GET /api/tech-colors/palette``).
// Removing keeps a single source of truth on the wire.

const SECTIONS = [
  { k: "dispatch",   label: "Dispatch",     icon: Truck },
  { k: "schedule",   label: "Schedule",     icon: Calendar },
  { k: "routes",     label: "Routes",       icon: Route },
  { k: "workstream", label: "Work Stream",  icon: Activity },
  { k: "crews",      label: "Crews",        icon: Users2 },
  { k: "team",       label: "Team",         icon: Users2 },
  { k: "timesheets", label: "Timesheets",   icon: ClipboardList },
  { k: "timeclock",  label: "Timeclock",    icon: Clock },
  { k: "coverage",   label: "Coverage",     icon: MapPin },
  { k: "maintenance",label: "Maintenance",  icon: Waves },
  // Phase Feb-2026 · Multi-industry Phase C — the pool tab is
  // gated by the tenant's ``pools`` industry. Landscape-only /
  // multi-industry-without-pools tenants no longer see this row.
  { k: "pool",       label: "Pool Service", icon: Waves, industry: "pools" },
  { k: "equipment",  label: "Equipment",    icon: Wrench },
  { k: "pricebook",  label: "Price Book",   icon: Package },
  { k: "loghistory", label: "Log History",  icon: History },
