        <p style={{ color: colors.onSurfaceSecondary }}>
          They will be hidden from all rosters and their active jobs will
          be reassigned to the "Unassigned" placeholder. This can be
          undone by a super_admin.
        </p>
      </div>
    </Modal>
  );
}


